-- 21/10/2026 — a trilha engenharia-dados.
--
-- A quarta trilha. As três primeiras ensinam a treinar modelo e a usar
-- LLM; nenhuma responde de onde vem o dado que elas consomem — e essa é
-- a parte que erra em silêncio: pipeline quebrado não dá erro, dá
-- resposta. Daí a insistência desta trilha em idempotência, teste sobre
-- o dado e reprocessamento, em vez de numa lista de ferramentas.
--
-- ordem 30 porque as existentes andam de dez em dez (0, 10, 20), o que
-- deixa espaço para inserir trilha entre duas sem reescrever as outras.
--
-- 5 etapas, 13 grupos, 84 tópicos — contagem conferida aqui, mas quem
-- a grava é o gatilho trilha_contagem, não este insert.

insert into public.trilha (id, rotulo, cor, rota, ordem, publicada, conteudo)
values ('engenharia-dados', 'Engenharia de Dados', '#9e5b2b',
        '[[24, 212], [88, 196], [150, 142], [214, 122], [278, 36]]'::jsonb, 30, true,
        $json${"ROADMAP": {"titulo": "Engenharia de Dados", "subtitulo": "Do SQL ao pipeline em produção — 2026", "fonte": null, "etapas": [{"id": "fundacoes", "numero": 1, "titulo": "Fundações", "objetivo": "Consultar, mover e versionar dados com SQL, Python e a linha de comando, sem depender de interface gráfica.", "descricao": "Engenharia de dados é quase toda feita em cima de três ferramentas: uma linguagem para perguntar ao banco, uma para fazer o que o banco não faz, e um terminal para tudo o que acontece entre as duas. Quem pula esta etapa consegue montar um pipeline, mas não consegue consertá-lo: o defeito chega como \"o número está errado\", e a causa está num join que duplicou linhas, num fuso horário ou num arquivo com encoding diferente do esperado.\n\nO SQL aqui vai bem além do select. É a parte em que você aprende a desconfiar do próprio resultado.", "preRequisitos": "Nenhum", "duracao": "4–6 semanas", "grupos": [{"id": "g-de-sql", "titulo": "SQL", "descricao": "A linguagem em que o trabalho acontece. Estude num banco de verdade — Postgres ou DuckDB local —, não num simulador de navegador.", "topicos": [{"id": "de-sql-01", "titulo": "Selecionar e filtrar", "prioridade": "fundamental", "desc": "select, where, order by, limit, distinct", "detalhe": "Comece lendo dado que você não criou: um dump público, um CSV grande de verdade. O hábito a formar aqui é olhar antes de agregar — `select * ... limit 20` é barato e evita que você passe uma hora explicando um total que estava errado desde a primeira linha.\n\nO erro típico é usar `distinct` como conserto. Quando ele muda o resultado, está escondendo uma duplicação que veio de outro lugar, e você vai reencontrá-la mais tarde, maior."}, {"id": "de-sql-02", "titulo": "Agregar e agrupar", "prioridade": "fundamental", "desc": "group by, having, count, sum, avg, count distinct", "detalhe": "A regra que organiza tudo: toda coluna no `select` ou está no `group by` ou está dentro de uma agregação. Entenda que `count(*)` conta linhas e `count(coluna)` conta valores não nulos — os dois diferirem é informação, não ruído.\n\n`having` filtra depois de agregar, `where` filtra antes. Trocar os dois muda o resultado e não dá erro: é um dos poucos lugares do SQL onde a resposta errada parece certa."}, {"id": "de-sql-03", "titulo": "Junções", "prioridade": "fundamental", "desc": "inner join, left join, full join, cross join, anti-join", "detalhe": "Junção é onde pipeline de dados morre, e erra nos dois sentidos: o `inner join` que descarta em silêncio as linhas sem par, e o join sobre um lado não único que multiplica linhas — o fan-out, que infla todo `sum` depois dele.\n\nO hábito que previne os dois é contar as linhas antes e depois de cada join. Subiu, o lado direito não era único na chave; caiu, havia órfãos que alguém precisa explicar. O anti-join (`left join ... where b.id is null`) é a ferramenta para investigar o segundo caso."}, {"id": "de-sql-04", "titulo": "Subconsultas e CTEs", "prioridade": "fundamental", "desc": "with, subconsulta correlacionada, exists, in", "detalhe": "Um `with` nomeado transforma uma consulta ilegível numa sequência de passos com nome, e é assim que toda transformação séria é escrita. Escreva em CTEs mesmo quando caberia numa linha: a próxima pessoa a depurar aquilo é provavelmente você.\n\nCuidado com `in` sobre subconsulta que pode devolver nulo — a lógica de três valores faz `not in` devolver vazio em vez do que você esperava. `exists` não tem esse problema e é o padrão mais seguro."}, {"id": "de-sql-05", "titulo": "Funções de janela", "prioridade": "fundamental", "desc": "row_number, rank, lag, lead, sum over, partition by", "detalhe": "A diferença entre janela e agregação: a janela olha um conjunto de linhas e devolve uma linha para cada entrada, sem colapsar nada. É o que resolve deduplicação, variação contra o período anterior e acumulado.\n\nSe você levar uma coisa só desta etapa, que seja `row_number() over (partition by chave order by atualizado_em desc) = 1`: ela aparece em praticamente todo pipeline que ingere o mesmo registro mais de uma vez — ou seja, em todos."}, {"id": "de-sql-06", "titulo": "Tipos, nulos e tempo", "prioridade": "fundamental", "desc": "cast, coalesce, nulo em comparação e em agregação, timestamp com e sem fuso", "detalhe": "Nulo não é zero nem string vazia, e qualquer comparação com ele resulta em nulo — por isso `where coluna != 'x'` descarta as linhas nulas sem avisar. Saiba quando usar `coalesce` e quando o nulo é a resposta honesta.\n\nFuso horário é o defeito mais caro desta lista porque erra por horas, não por ordem de grandeza: o resultado continua plausível. Guarde tudo em UTC, converta só na apresentação, e desconfie de todo relatório diário cujo pico esteja encostado na meia-noite."}, {"id": "de-sql-07", "titulo": "Ler um plano de execução", "prioridade": "importante", "desc": "explain, explain analyze, varredura completa, estimativa de linhas", "detalhe": "Consulta lenta raramente melhora por reescrita adivinhada. Rode `explain analyze` e compare as linhas estimadas com as reais: quando a estimativa erra por muito, o otimizador escolheu o plano errado porque a estatística está velha ou porque o filtro está dentro de uma função que impede o índice.\n\nVarredura completa não é defeito por si — em tabela pequena ela vence o índice. O que importa é se o volume lido faz sentido para o resultado devolvido."}, {"id": "de-sql-08", "titulo": "Índices", "prioridade": "importante", "desc": "b-tree, índice composto e a ordem das colunas, índice parcial, custo na escrita", "detalhe": "Índice acelera leitura e encarece escrita — num pipeline que carrega milhões de linhas por hora isso é uma troca real, não teórica. Em carga grande, vale derrubar o índice, carregar e recriar.\n\nEm índice composto a ordem das colunas decide quais consultas ele atende: um índice em `(a, b)` serve a filtro por `a` e por `a, b`, mas não a filtro só por `b`. É a confusão mais comum de quem cria índice por intuição."}, {"id": "de-sql-09", "titulo": "DDL e transações", "prioridade": "importante", "desc": "create table, alter table, constraint, begin, commit, rollback", "detalhe": "Restrições — chave primária, `unique`, `not null`, chave estrangeira — são a única validação que o banco aplica sempre, inclusive contra o script que alguém roda à mão às duas da manhã. Teste de pipeline não substitui isso.\n\nTransação é o que torna a carga segura: ou a tabela inteira trocou, ou nada mudou. Pipeline que apaga e insere fora de transação tem uma janela em que o relatório lê a tabela vazia — e no painel isso aparece como zero, não como erro."}, {"id": "de-sql-10", "titulo": "Views e consulta reutilizável", "prioridade": "opcional", "desc": "view, materialized view, refresh", "detalhe": "View é consulta com nome: nenhum armazenamento e nenhum ganho de desempenho. View materializada guarda o resultado e precisa ser atualizada, o que a transforma num pequeno pipeline — com tudo o que isso traz de dado velho silencioso.\n\nSaiba a diferença antes de escolher, porque o nome parecido esconde que uma das duas introduz atraso."}]}, {"id": "g-de-python", "titulo": "Python para dados", "descricao": "O pedaço de Python que aparece em pipeline. Não é a linguagem inteira.", "topicos": [{"id": "de-py-01", "titulo": "Ambiente reproduzível", "prioridade": "fundamental", "desc": "venv ou uv, dependências fixadas, pyproject, um ambiente por projeto", "detalhe": "Fixe versões. \"Funciona na minha máquina\", em dados, costuma ser uma biblioteca que mudou o comportamento padrão de leitura de datas — e o resultado é um número errado, não uma exceção.\n\nNão use o interpretador do sistema para nada. Um ambiente por projeto, criado por um comando que está escrito no README."}, {"id": "de-py-02", "titulo": "Estruturas e iteração preguiçosa", "prioridade": "fundamental", "desc": "dict, set, list comprehension, generator, yield, itertools", "detalhe": "A pergunta que separa script de pipeline: isto cabe na memória? Gerador processa linha a linha e roda com arquivo maior que a RAM; lista materializada não. Trocar `[...]` por `(...)` às vezes é toda a diferença entre rodar e ter o processo encerrado pelo sistema.\n\n`set` e `dict` dão busca em tempo constante. Procurar membro numa lista dentro de um laço é o padrão que transforma um minuto em uma hora quando o volume cresce."}, {"id": "de-py-03", "titulo": "Arquivos e formatos de texto", "prioridade": "fundamental", "desc": "csv, json, jsonl, encoding, delimitador, leitura em blocos", "detalhe": "CSV não é um formato, é um costume: delimitador, aspas, quebra de linha dentro de campo e encoding variam conforme quem gerou. Use a biblioteca de CSV em vez de partir a linha pela vírgula — o primeiro campo com vírgula dentro de aspas quebra a versão improvisada.\n\nJSONL, um objeto por linha, é o que se lê em streaming; JSON de array único exige carregar tudo. Ao receber arquivo de terceiro, abra os primeiros bytes antes de confiar na extensão."}, {"id": "de-py-04", "titulo": "pandas", "prioridade": "fundamental", "desc": "DataFrame, dtypes, merge, groupby, apply, uso de memória", "detalhe": "Duas coisas importam mais que a API: os `dtypes` e a memória. Coluna lida como `object` é string disfarçada, e ela faz agregação devolver concatenação em vez de soma — confira `df.dtypes` logo depois de ler, sempre.\n\n`apply` sobre linha é um laço Python fantasiado de vetorização, e é a causa mais frequente de transformação lenta. Antes de otimizar, pergunte se aquilo não deveria estar no SQL: trazer dez milhões de linhas para filtrar no pandas é mover o trabalho para o lugar mais fraco do sistema."}, {"id": "de-py-05", "titulo": "Falar com o banco pelo código", "prioridade": "fundamental", "desc": "DBAPI, SQLAlchemy, consulta parametrizada, cursor, carga em lote", "detalhe": "Nunca monte SQL concatenando string, nem em script interno: parâmetro existe para isso e, além de barrar injeção, ele cuida de aspas, nulo e fuso sem que você pense neles.\n\nPara carga, `insert` linha a linha num laço é lento por ida e volta de rede, não por CPU. Use carga em lote ou o comando de cópia em massa do banco — a diferença costuma ser de duas ordens de grandeza."}, {"id": "de-py-06", "titulo": "Log, erro e teste", "prioridade": "importante", "desc": "logging, exceção, pytest, amostra pequena de dado", "detalhe": "`print` some no log do orquestrador sem nível nem horário. Use `logging` desde o primeiro script e registre o que você vai querer saber às três da manhã: quantas linhas entraram, quantas saíram, quanto tempo levou.\n\nTeste de pipeline é teste da transformação sobre um arquivo minúsculo com os casos chatos dentro — nulo, duplicata, acento, data na virada do mês. Não precisa de infraestrutura nenhuma, e é o teste que de fato pega defeito."}, {"id": "de-py-07", "titulo": "Tipagem e validação na borda", "prioridade": "opcional", "desc": "type hints, dataclass, pydantic, falhar cedo", "detalhe": "Validar o registro assim que ele entra transforma um erro silencioso no meio do pipeline numa falha com nome e linha. É o mesmo princípio das restrições do banco, aplicado antes de chegar nele.\n\nTipagem em Python não é verificada em tempo de execução: ela vale pela leitura e pelas ferramentas, não como garantia."}]}, {"id": "g-de-shell", "titulo": "Terminal, Git e contêiner", "topicos": [{"id": "de-sh-01", "titulo": "Linha de comando", "prioridade": "fundamental", "desc": "navegação, find, less, redirecionamento, pipe, ssh", "detalhe": "Boa parte do trabalho acontece em máquina remota sem interface. Inspecionar um arquivo de 40 GB sem abri-lo — `head`, `less`, `wc -l` — é rotina, não truque.\n\nO pipe é o conceito central: programas pequenos encadeados sobre um fluxo. É a mesma ideia dos estágios de um pipeline de dados, em escala de uma linha."}, {"id": "de-sh-02", "titulo": "Processar texto no terminal", "prioridade": "importante", "desc": "grep, cut, sort, uniq, awk, jq", "detalhe": "Antes de escrever código para descobrir por que um arquivo não carregou, conte os delimitadores por linha com `awk` e ache a linha diferente. É um diagnóstico de dez segundos no lugar de meia hora de depuração.\n\n`jq` faz o mesmo para JSON e é indispensável para olhar a resposta de uma API antes de escrever o cliente dela."}, {"id": "de-sh-03", "titulo": "Git", "prioridade": "fundamental", "desc": "commit, branch, merge, pull request, revisão", "detalhe": "Transformação de dados é código: vive em repositório, com revisão. O motivo não é organização — é poder responder \"o que mudou no dia em que o número mudou\", que é a primeira pergunta de todo incidente de dado.\n\nMensagem de commit que diz o porquê vale mais que uma que repete o diff."}, {"id": "de-sh-04", "titulo": "Configuração e segredo", "prioridade": "fundamental", "desc": "variável de ambiente, .env fora do versionamento, cofre de segredos", "detalhe": "Credencial não entra no repositório. Uma vez enviada, ela está no histórico mesmo depois de apagada do arquivo, e rotacioná-la é o único conserto de verdade.\n\nA mesma separação resolve ambiente: o mesmo código aponta para desenvolvimento ou produção pela configuração, nunca por linha comentada."}, {"id": "de-sh-05", "titulo": "Docker", "prioridade": "importante", "desc": "imagem, contêiner, volume, docker compose", "detalhe": "Contêiner é o que faz o pipeline rodar igual na sua máquina e no orquestrador, e é como quase todo serviço de dados é distribuído hoje. Subir Postgres, Kafka ou Airflow localmente com `compose` é o jeito de estudar as próximas etapas sem pagar nuvem.\n\nEntenda volume cedo: dado dentro do contêiner some quando ele morre, e essa é a primeira surpresa de todo mundo."}]}]}, {"id": "modelagem", "numero": 2, "titulo": "Modelagem e armazenamento", "objetivo": "Escolher modelo, formato e particionamento a partir do padrão de consulta, e justificar a escolha.", "descricao": "Aqui se decide o que custa caro depois. Modelo de dados e formato de arquivo são as duas escolhas que ninguém revisita: quando a tabela tem um ano e cinquenta painéis em cima, mudar o grão é um projeto, não uma correção.\n\nA pergunta que organiza a etapa inteira não é \"qual é a modelagem certa\", é \"quem vai consultar isto, e como\". Banco transacional e armazém analítico querem formatos opostos pelo mesmo motivo: um lê poucas linhas inteiras, o outro lê poucas colunas de muitas linhas.", "preRequisitos": "Etapa 1", "duracao": "3–4 semanas", "grupos": [{"id": "g-de-modelo", "titulo": "Modelo de dados", "topicos": [{"id": "de-mod-01", "titulo": "OLTP e OLAP", "prioridade": "fundamental", "desc": "carga transacional, carga analítica, por que os dois modelos divergem", "detalhe": "Sistema transacional é otimizado para escrever e ler poucas linhas inteiras com consistência; sistema analítico, para varrer poucas colunas de bilhões de linhas. Daí tudo mais: normalização lá, redundância cá; linha aqui, coluna ali.\n\nEntender isso é o que impede o erro inaugural da área — rodar relatório pesado direto na base de produção e derrubar o aplicativo."}, {"id": "de-mod-02", "titulo": "Normalização", "prioridade": "fundamental", "desc": "primeira, segunda e terceira forma normal, anomalia de atualização", "detalhe": "Normalizar é eliminar repetição para que um fato viva num lugar só. O ganho concreto não é estético: é que atualizar o endereço de um cliente não deixa cinco cópias divergentes pelo banco.\n\nAprenda isso mesmo que você vá trabalhar sobretudo com modelo dimensional, porque é na origem normalizada que você lê os dados — e porque desnormalizar de propósito só é defensável depois de saber o que você está abrindo mão."}, {"id": "de-mod-03", "titulo": "Modelagem dimensional", "prioridade": "fundamental", "desc": "tabela fato, tabela dimensão, esquema estrela, esquema floco de neve", "detalhe": "Fato guarda o que aconteceu e é comprida; dimensão guarda o contexto e é larga. O esquema estrela é redundante de propósito: ele troca espaço, que é barato, por menos junções na consulta, que é o que o analista paga.\n\nFloco de neve normaliza a dimensão e quase nunca compensa num armazém moderno — custa junção para economizar um armazenamento que já não é o gargalo."}, {"id": "de-mod-04", "titulo": "O grão da tabela fato", "prioridade": "fundamental", "desc": "definir o grão em uma frase, misturar grãos, fato agregado", "detalhe": "O grão é a frase que define o que é uma linha: \"uma linha por item de pedido\", \"uma linha por sessão por dia\". Escreva-a antes de criar a tabela, e verifique que a chave da tabela corresponde a ela.\n\nMisturar grãos é o defeito estrutural clássico: quando a mesma tabela tem linha de pedido e linha de item, todo `sum` conta o valor do pedido mais de uma vez. Não dá erro e o painel fica errado por meses."}, {"id": "de-mod-05", "titulo": "Dimensões que mudam", "prioridade": "importante", "desc": "SCD tipo 1, SCD tipo 2, data de validade, registro corrente", "detalhe": "O cliente mudou de cidade: você sobrescreve (tipo 1) e perde a história, ou guarda uma linha nova com validade (tipo 2) e consegue responder quanto ele comprou enquanto morava lá. A escolha é da pergunta de negócio, não técnica.\n\nTipo 2 complica toda junção — a partir dele você junta por chave e por data, e esquecer a segunda condição duplica linhas. É por isso que ele só se adota quando alguém vai mesmo usar a história."}, {"id": "de-mod-06", "titulo": "Chaves", "prioridade": "importante", "desc": "chave natural, chave substituta, chave composta, hash de chave", "detalhe": "Chave natural vem da origem e muda quando a origem muda de ideia; chave substituta é sua e é estável. Em dimensão tipo 2 a substituta deixa de ser opcional: a chave natural passa a repetir por linha de versão.\n\nChave por hash das colunas de negócio é o atalho comum em lakehouse porque é calculável sem sequência central, o que importa quando a carga é distribuída. Fixe o algoritmo e a ordem das colunas, porque mudar qualquer um reescreve todas as chaves."}, {"id": "de-mod-07", "titulo": "Dado semiestruturado", "prioridade": "importante", "desc": "JSON em coluna, achatar estrutura, esquema sobre leitura", "detalhe": "Guardar o payload cru numa coluna JSON preserva o que você ainda não sabe que vai precisar, e é a prática certa na camada de entrada. O erro é parar aí: consulta sobre JSON é mais cara e mais frágil, então as colunas que o negócio usa precisam ser extraídas para colunas de verdade na camada seguinte.\n\nEsquema sobre leitura adia o problema do esquema, não o resolve. Alguém vai descobrir a mudança de contrato — a questão é se vai ser na carga ou no relatório."}, {"id": "de-mod-08", "titulo": "Outros modelos", "prioridade": "opcional", "desc": "Data Vault, One Big Table, modelo de atividade", "detalhe": "Data Vault separa chaves, relações e atributos para absorver mudança de origem sem reescrever o histórico; é pesado e faz sentido em organização com muitas origens instáveis e exigência de auditoria. Tabela única e larga vai no outro extremo e se apoia no fato de que armazém colunar só lê a coluna pedida.\n\nConheça os dois para não achar que estrela é a única opção — e para reconhecer quando a sua está brigando contra o problema."}]}, {"id": "g-de-arquivo", "titulo": "Formato, arquivo e lake", "topicos": [{"id": "de-arq-01", "titulo": "Linha contra coluna", "prioridade": "fundamental", "desc": "armazenamento por linha, armazenamento por coluna, quando cada um vence", "detalhe": "Em formato colunar, `select uma_coluna from tabela` lê só aquela coluna do disco. É daí que sai o salto de desempenho analítico, e também por que `select *` é um antipadrão caro nesses sistemas — o oposto do que você aprendeu no banco transacional.\n\nColunar também comprime muito melhor, porque valores parecidos ficam juntos. Os dois efeitos têm a mesma causa."}, {"id": "de-arq-02", "titulo": "Parquet", "prioridade": "fundamental", "desc": "row group, estatística por coluna, predicate pushdown, esquema embutido", "detalhe": "Parquet é o formato padrão do armazenamento analítico e carrega o próprio esquema e os tipos — o que já o põe uma categoria acima do CSV, onde toda leitura adivinha os tipos de novo.\n\nAs estatísticas de mínimo e máximo por row group são o que permite pular blocos inteiros sem lê-los. Essa é a razão de o filtro ter que chegar ao leitor: filtrar depois de carregar em memória desliga a otimização."}, {"id": "de-arq-03", "titulo": "Compressão", "prioridade": "importante", "desc": "snappy, zstd, gzip, custo de CPU contra custo de E/S", "detalhe": "A escolha é entre gastar CPU e gastar rede e disco. Snappy descomprime rápido e comprime pouco; zstd é o meio-termo que virou padrão novo; gzip comprime bem e é lento. Em nuvem, onde você paga por byte lido, isso é dinheiro.\n\nFormato não divisível comprimido — um CSV grande em gzip — é a armadilha: o arquivo inteiro vira uma tarefa só, e seu cluster de vinte máquinas processa com uma."}, {"id": "de-arq-04", "titulo": "Particionamento", "prioridade": "fundamental", "desc": "partição por data, poda de partição, cardinalidade da chave, arquivos pequenos", "detalhe": "Particionar por data e filtrar por data faz o motor ler uma pasta em vez da tabela toda. Particionar por algo de alta cardinalidade — id de usuário — cria milhões de pastas com um arquivo minúsculo cada, e o custo de abrir arquivo passa a dominar o processamento.\n\nO problema dos arquivos pequenos é o mais comum de todos, e vem de pipeline que escreve a cada poucos minutos. A solução é compactação periódica, e saber que ela existe evita o diagnóstico errado de \"o cluster está pequeno\"."}, {"id": "de-arq-05", "titulo": "Data lake em camadas", "prioridade": "fundamental", "desc": "bronze, prata, ouro, zona de pouso, imutabilidade do dado cru", "detalhe": "A camada crua é imutável e guarda o que chegou, exatamente como chegou. É o que permite reprocessar quando a regra de negócio mudar ou quando a transformação tiver defeito — sem ela, corrigir significa pedir os dados de novo para a origem, se ela ainda os tiver.\n\nAs camadas seguintes são derivadas e, por isso, descartáveis: reconstruí-las do cru precisa ser rotina, não aventura."}, {"id": "de-arq-06", "titulo": "Formatos de tabela", "prioridade": "importante", "desc": "Iceberg, Delta Lake, Hudi, snapshot, time travel, escrita atômica", "detalhe": "Um diretório de Parquet não tem transação: quem lê no meio da escrita vê metade dos arquivos. Os formatos de tabela acrescentam um log de metadados por cima, e é isso que traz escrita atômica, leitura consistente, `merge` e a volta a um estado anterior.\n\nO time travel não é curiosidade: é o que permite responder \"o número de ontem era esse mesmo?\" depois de um reprocessamento — a pergunta que todo incidente de dado faz."}, {"id": "de-arq-07", "titulo": "Catálogo e evolução de esquema", "prioridade": "importante", "desc": "metastore, coluna nova, coluna removida, mudança de tipo", "detalhe": "O catálogo é quem diz onde a tabela está e qual é o esquema dela; sem ele, cada ferramenta descobre por conta própria e elas discordam.\n\nAcrescentar coluna é seguro; remover ou mudar tipo quebra quem consome. Trate mudança de esquema como mudança de API pública, com aviso e período de convivência — a diferença é que aqui o consumidor quebrado é um painel que alguém olha na segunda de manhã."}]}]}, {"id": "pipelines", "numero": 3, "titulo": "Ingestão, transformação e orquestração", "objetivo": "Construir um pipeline que possa rodar duas vezes sem estragar o resultado e ser reprocessado sem medo.", "descricao": "Esta é a etapa que dá nome à profissão. O que separa um pipeline de um script agendado são duas propriedades: ele é idempotente — rodar de novo não duplica nada — e é reprocessável — dá para pedir que ele refaça março inteiro.\n\nNenhuma das duas aparece sozinha. Elas vêm de decisões específicas sobre chave, janela de leitura e forma de escrita, e é nelas que esta etapa insiste. Ferramenta aqui é consequência, não começo: Airflow e dbt resolvem bem problemas que você precisa reconhecer primeiro.", "preRequisitos": "Etapas 1 e 2", "duracao": "5–7 semanas", "grupos": [{"id": "g-de-ingestao", "titulo": "Ingestão", "topicos": [{"id": "de-ing-01", "titulo": "Carga completa e carga incremental", "prioridade": "fundamental", "desc": "full load, marca d'água, coluna de atualização, janela de atraso", "detalhe": "Comece com carga completa: ela é simples, idempotente de graça, e enquanto a tabela couber na janela de execução não há motivo para complicar. Troque por incremental quando ela não couber mais, não antes.\n\nIncremental por marca d'água tem um furo conhecido: o registro gravado na origem com horário anterior ao seu último corte, que chega depois dele e nunca é lido. Por isso se relê uma janela de segurança sobreposta — e por isso a escrita precisa ser por `merge`, não por `insert`."}, {"id": "de-ing-02", "titulo": "Idempotência", "prioridade": "fundamental", "desc": "merge, upsert, chave de deduplicação, sobrescrever partição", "detalhe": "Rodar duas vezes é normal: a tarefa falhou no meio, alguém reexecutou, o orquestrador tentou de novo. Se a segunda execução duplica linhas, o pipeline é um script.\n\nDois padrões resolvem quase tudo. `merge` por chave de negócio, que atualiza o que existe e insere o que falta; ou sobrescrever a partição inteira do dia processado, que é mais simples e costuma ser melhor quando o dado é particionado por data. Escolha um e seja consistente."}, {"id": "de-ing-03", "titulo": "Captura de mudança", "prioridade": "importante", "desc": "CDC por log, Debezium, snapshot inicial, exclusão lógica", "detalhe": "CDC lê o log de transações do banco de origem e entrega insert, update e delete como eventos, sem consultar a tabela nem pesar na produção. É o jeito certo de replicar um banco transacional.\n\nDois detalhes derrubam quem começa: o snapshot inicial, que precisa se encaixar no fluxo contínuo sem lacuna nem duplicata, e o delete — consulta por marca d'água jamais vê exclusão, e é por isso que tabela replicada \"na mão\" acumula registro que já não existe na origem."}, {"id": "de-ing-04", "titulo": "Consumir APIs", "prioridade": "fundamental", "desc": "paginação, limite de taxa, repetição com espera crescente, falha parcial", "detalhe": "Toda API de verdade pagina, limita e falha no meio. Repetição com espera crescente e um teto é o mínimo; e precisa saber retomar da página onde parou, senão a falha na página 900 custa as 900 anteriores.\n\nGrave a resposta crua antes de transformar. Quando o número sair errado, a pergunta vai ser \"a origem mandou isso ou nós estragamos\", e sem o cru você não responde."}, {"id": "de-ing-05", "titulo": "Arquivos que chegam", "prioridade": "importante", "desc": "zona de pouso, arquivo ainda sendo escrito, manifesto, convenção de nome", "detalhe": "O defeito clássico: o pipeline lê um arquivo que ainda está sendo enviado e processa metade dele, sem erro nenhum. Resolve-se com manifesto, arquivo-sentinela ou escrita em nome temporário com renomeação atômica no fim.\n\nNome de arquivo com data e lote não é burocracia: é o que permite saber o que já foi processado quando a origem reenviar o mesmo dia."}, {"id": "de-ing-06", "titulo": "Ingestão de eventos", "prioridade": "importante", "desc": "esquema do evento, campo obrigatório, versão do evento, fila de descarte", "detalhe": "Evento é dado que você não pode pedir de novo: se o consumidor rejeita a mensagem, ela se perde. Daí a fila de descarte, onde o que não pôde ser processado espera em vez de sumir.\n\nVersione o esquema do evento desde o primeiro dia. Produtor que acrescenta campo não quebra ninguém; produtor que renomeia um campo quebra todo consumidor de uma vez, e o único jeito de notar é o número cair para zero."}]}, {"id": "g-de-transformacao", "titulo": "Transformação", "topicos": [{"id": "de-trf-01", "titulo": "ETL e ELT", "prioridade": "fundamental", "desc": "transformar antes de carregar, transformar depois, por que o ELT venceu", "detalhe": "Enquanto computação era cara e ficava fora do banco, transformar antes era obrigatório. Com armazém que escala computação sob demanda, carregar cru e transformar em SQL lá dentro é mais simples e muito mais reprocessável — o cru fica guardado.\n\nNão é regra universal: dado pessoal que não pode entrar, ou payload gigante que precisa ser reduzido na origem, continuam pedindo transformação antes."}, {"id": "de-trf-02", "titulo": "dbt", "prioridade": "fundamental", "desc": "model, ref, materialização, seed, grafo de dependências", "detalhe": "O dbt é SQL mais duas ideias. A primeira é `ref`, que substitui o nome da tabela por uma referência e, com isso, deduz o grafo de dependências a partir do próprio código — ninguém declara ordem de execução à mão.\n\nA segunda é materialização como configuração: a mesma consulta vira view, tabela ou carga incremental trocando uma linha. É o que permite começar simples e endurecer só o que ficou lento."}, {"id": "de-trf-03", "titulo": "Camadas de transformação", "prioridade": "fundamental", "desc": "staging, intermediate, marts, uma responsabilidade por camada", "detalhe": "Staging só renomeia, tipa e limpa, um modelo por tabela de origem; intermediate faz junção e regra de negócio; marts entrega o que o negócio consulta. A disciplina parece burocrática até o dia em que a origem muda um nome de coluna e o conserto é num arquivo só.\n\nO sinal de que a camada foi pulada é a mesma regra de negócio reescrita em três painéis, com três resultados."}, {"id": "de-trf-04", "titulo": "Testes de dado na transformação", "prioridade": "fundamental", "desc": "unique, not_null, accepted_values, relationships, teste próprio em SQL", "detalhe": "Teste de dado roda contra o dado, não contra o código: ele afirma que a chave é única hoje, com os dados de hoje. É o que pega a mudança silenciosa na origem — o defeito que teste unitário jamais vê.\n\nComece pelos dois que pagam a conta sozinhos: unicidade da chave primária de todo modelo e não nulo nas colunas de junção. Eles capturam fan-out e órfão, que são as duas falhas de junção da etapa 1."}, {"id": "de-trf-05", "titulo": "Documentação e linhagem", "prioridade": "importante", "desc": "descrição de coluna, grafo de linhagem, análise de impacto", "detalhe": "Linhagem responde às duas perguntas urgentes: se eu mudar esta coluna, o que quebra; e, quando este painel está errado, por onde o número passou. Num projeto com `ref`, o grafo vem de graça — é um dos maiores ganhos do modelo.\n\nDescrição de coluna é o que impede a quinta pessoa de perguntar se \"receita\" é com ou sem imposto. Escreva a definição onde o dado mora, não num documento à parte que envelhece sozinho."}]}, {"id": "g-de-orquestracao", "titulo": "Orquestração", "topicos": [{"id": "de-orq-01", "titulo": "DAG e dependência", "prioridade": "fundamental", "desc": "grafo acíclico, tarefa, dependência, paralelismo", "detalhe": "Orquestrador existe para responder \"o que pode rodar agora\" — e um agendador por horário não responde isso. Encadear por horário (\"a carga às 2h, o relatório às 3h\") funciona até o dia em que a carga demora uma hora e meia e o relatório lê a tabela de ontem, sem reclamar.\n\nDeclare a dependência, não o horário. É a diferença entre pipeline e alarme."}, {"id": "de-orq-02", "titulo": "Airflow", "prioridade": "fundamental", "desc": "DAG em Python, operator, sensor, intervalo de dados, scheduler", "detalhe": "A confusão que atrapalha todo mundo no começo: a data de execução é o início do intervalo processado, não o momento em que a tarefa roda. A execução de 1º de março roda depois que março terminou — porque ela processa março.\n\nEntenda isso cedo e o reprocessamento fica simples. Entenda errado e você escreve tarefas que usam \"hoje\" em vez do intervalo, o que torna impossível reexecutar o passado com resultado correto."}, {"id": "de-orq-03", "titulo": "Reprocessamento", "prioridade": "fundamental", "desc": "backfill, tarefa parametrizada pela janela, limite de concorrência", "detalhe": "Todo pipeline vai ser reprocessado: a regra mudou, houve defeito, a origem corrigiu o passado. Para isso a tarefa precisa receber a janela como parâmetro e escrever só nela — é a idempotência da ingestão aplicada ao tempo.\n\nLimite a concorrência do reprocessamento. Disparar 400 dias de uma vez contra o banco de origem é, na prática, um ataque de negação de serviço contra o seu próprio time."}, {"id": "de-orq-04", "titulo": "Falha, repetição e alerta", "prioridade": "fundamental", "desc": "retry, tempo limite, SLA, alerta acionável, falha silenciosa", "detalhe": "Repetição automática resolve falha transitória de rede e esconde defeito de lógica. Repita poucas vezes e com espera, e investigue a tarefa que precisa de repetição toda vez — ela não é instável, ela está errada.\n\nO pior desfecho não é a tarefa que falha, é a que termina sem fazer nada: zero linha lida, sucesso verde. Afirme o volume esperado e falhe de propósito quando ele não vier."}, {"id": "de-orq-05", "titulo": "Configuração e segredo na orquestração", "prioridade": "importante", "desc": "conexão, variável, segredo, mesmo código em vários ambientes", "detalhe": "Credencial fica no cofre do orquestrador, e o código pede por nome. Isso é o que permite ao mesmo DAG rodar em homologação e em produção sem edição — e é o que torna possível rotacionar uma senha sem abrir um pull request.\n\nSegredo impresso em log vaza do mesmo jeito que segredo commitado. Confira o que suas mensagens de erro imprimem."}]}]}, {"id": "escala", "numero": 4, "titulo": "Escala e tempo real", "objetivo": "Processar volume que não cabe numa máquina e entender o custo de reduzir a latência.", "descricao": "Distribuir é caro em complexidade, e a primeira pergunta honesta desta etapa é se você precisa mesmo. Uma máquina grande com DuckDB ou Polars resolve dezenas de gigabytes mais rápido que um cluster mal configurado, sem shuffle, sem driver, sem fila de alocação.\n\nQuando você precisa, o que importa é entender como o dado se move entre máquinas — porque é no movimento, e só nele, que está o custo. Streaming vem depois pelo mesmo motivo: ele não é batch mais rápido, é um modelo diferente em que tempo e ordem viram problema seu.", "preRequisitos": "Etapa 3", "duracao": "5–7 semanas", "grupos": [{"id": "g-de-distribuido", "titulo": "Processamento distribuído", "topicos": [{"id": "de-spk-01", "titulo": "Quando não distribuir", "prioridade": "fundamental", "desc": "limite de uma máquina só, DuckDB, Polars, custo fixo do cluster", "detalhe": "Faça a conta antes: quanto o dado ocupa comprimido, quanta memória a máquina tem, quanto tempo a execução precisa durar. Muita coisa que se joga num cluster roda em minutos num notebook com um motor colunar local.\n\nCluster tem custo fixo — tempo de subida, serialização, shuffle, configuração — que só se paga acima de um volume. Saber onde fica esse limiar é o conhecimento mais útil deste grupo."}, {"id": "de-spk-02", "titulo": "Modelo de execução do Spark", "prioridade": "fundamental", "desc": "driver, executor, job, stage, task, partição", "detalhe": "O driver monta o plano e distribui tarefas; os executores processam partições. Uma tarefa por partição é o modelo mental que explica quase todo comportamento: poucas partições deixam máquinas ociosas, partições demais afogam o escalonador.\n\nA fronteira entre stages é um shuffle. Entender isso transforma o Spark UI de painel misterioso em mapa do custo."}, {"id": "de-spk-03", "titulo": "DataFrame e avaliação preguiçosa", "prioridade": "fundamental", "desc": "transformação, ação, plano lógico, otimizador", "detalhe": "Nada executa até uma ação pedir resultado; até lá, o Spark acumula um plano e o otimiza — reordena filtros, descarta colunas que ninguém usa. É por isso que a API de DataFrame bate escrever RDD à mão: o otimizador vê o que você pediu, não como você escreveu.\n\nO efeito prático é que `count()` dentro de um laço de depuração reexecuta o pipeline inteiro toda vez. Depurar sem saber disso dá a impressão de que o Spark é lento."}, {"id": "de-spk-04", "titulo": "Shuffle", "prioridade": "fundamental", "desc": "join, groupBy, repartition, custo de rede e disco", "detalhe": "Shuffle é redistribuir dado entre máquinas por chave, e é a operação cara: serializa, grava em disco, manda pela rede. Toda otimização séria de Spark é reduzir, evitar ou equilibrar shuffle.\n\nO atalho que mais rende é o broadcast join: quando um lado cabe na memória do executor, ele é copiado para todos e o join acontece sem mover o lado grande. Verifique no plano que ele foi escolhido — o Spark o decide por estimativa, e estimativa velha erra."}, {"id": "de-spk-05", "titulo": "Dado desbalanceado", "prioridade": "importante", "desc": "skew, chave dominante, salting, partição gigante", "detalhe": "Quando 90% das linhas têm a mesma chave, uma tarefa recebe 90% do trabalho e as outras 199 esperam por ela. O sintoma é inconfundível: quase todas as tarefas terminam rápido e uma fica horas.\n\nO conserto é quebrar a chave dominante acrescentando um sufixo aleatório e agregando em dois passos. Antes disso, pergunte se aquela chave — tipicamente nulo ou \"desconhecido\" — precisava mesmo entrar no join."}, {"id": "de-spk-06", "titulo": "Cache e reuso", "prioridade": "importante", "desc": "cache, persist, nível de armazenamento, quando não vale", "detalhe": "Cache vale quando o mesmo DataFrame é usado mais de uma vez e recalculá-lo é caro. Usado em todo lugar, ele consome a memória que a execução precisava e piora tudo — inclusive forçando derramamento para disco.\n\nAntes de cachear, veja se o problema não é o pipeline sendo reexecutado por uma ação que você nem queria ter chamado."}, {"id": "de-spk-07", "titulo": "Ler o Spark UI", "prioridade": "importante", "desc": "duração por stage, distribuição das tarefas, spill, GC, plano físico", "detalhe": "Olhe três coisas, nesta ordem: qual stage domina o tempo, se as tarefas desse stage têm duração parecida e se houve derramamento para disco. Elas apontam, respectivamente, para o lugar certo, para skew e para memória insuficiente.\n\nOtimizar Spark sem abrir o UI é adivinhar. Com ele, quase todo problema tem uma assinatura visual reconhecível."}, {"id": "de-spk-08", "titulo": "Motores de consulta", "prioridade": "opcional", "desc": "Trino, Athena, consulta federada, separação de computação e armazenamento", "detalhe": "Motor de consulta lê o lake direto e serve SQL interativo sem copiar dado para dentro de um armazém. É o que viabiliza o lakehouse: mesmos arquivos, vários motores por cima.\n\nA conta aqui é por byte varrido, o que devolve particionamento e formato colunar ao centro da conversa — a mesma decisão da etapa 2 aparece agora como linha na fatura."}]}, {"id": "g-de-streaming", "titulo": "Streaming", "topicos": [{"id": "de-str-01", "titulo": "Batch e streaming", "prioridade": "fundamental", "desc": "latência exigida, custo operacional, micro-batch, quando batch basta", "detalhe": "Comece perguntando quem decide o quê com esse dado e em quanto tempo. \"Tempo real\" quase sempre quer dizer \"não quero esperar até amanhã\", e isso se resolve rodando o batch de hora em hora — por uma fração do custo e da complexidade.\n\nStreaming de verdade se justifica quando a decisão é automática e imediata: antifraude, limite de crédito, alerta operacional. Fora disso é escolha cara travestida de modernidade."}, {"id": "de-str-02", "titulo": "Kafka", "prioridade": "fundamental", "desc": "tópico, partição, offset, grupo de consumidores, retenção", "detalhe": "Kafka é um log particionado, não uma fila: a mensagem não some ao ser lida, e o consumidor guarda até onde leu. É isso que permite reprocessar voltando o offset — a versão streaming do reprocessamento da etapa 3.\n\nA ordem é garantida dentro da partição, e só. Se a ordem importa por entidade, a chave da mensagem precisa ser a entidade, para que todos os eventos dela caiam na mesma partição."}, {"id": "de-str-03", "titulo": "Garantias de entrega", "prioridade": "fundamental", "desc": "at-most-once, at-least-once, exactly-once, consumidor idempotente", "detalhe": "Na prática você escolhe entre perder mensagem e processar a mesma duas vezes. Quase sempre se escolhe a segunda e se resolve a duplicata com consumidor idempotente — o que, de novo, é a chave de deduplicação da etapa 3.\n\n\"Exactly-once\" existe, mas com escopo definido: dentro do mesmo sistema e com estado transacional. Entre sistemas diferentes, continua sendo at-least-once mais idempotência."}, {"id": "de-str-04", "titulo": "Tempo de evento e tempo de processamento", "prioridade": "fundamental", "desc": "event time, processing time, marca d'água, evento atrasado", "detalhe": "O evento aconteceu às 23h58 e chegou às 00h03. Em qual dia ele conta? Agrupar por tempo de processamento é mais fácil e dá resposta errada; agrupar por tempo de evento está certo e obriga a decidir quanto tempo esperar pelos atrasados.\n\nA marca d'água é essa decisão escrita: até quando a janela permanece aberta. Curta demais, você descarta dado bom; longa demais, segura estado e atrasa o resultado — e não há valor universalmente certo."}, {"id": "de-str-05", "titulo": "Janelas", "prioridade": "importante", "desc": "janela fixa, janela deslizante, janela de sessão, agregação com estado", "detalhe": "Fixa responde \"por minuto\"; deslizante suaviza para alerta; sessão agrupa atividade separada por inatividade e é a que mais se parece com comportamento de pessoa.\n\nToda janela guarda estado, e estado é o que torna streaming operacionalmente pesado: ele precisa sobreviver à reinicialização do processo. É o motivo de o checkpoint não ser detalhe."}, {"id": "de-str-06", "titulo": "Frameworks de streaming", "prioridade": "importante", "desc": "Spark Structured Streaming, Flink, checkpoint, recuperação de falha", "detalhe": "Structured Streaming trata o fluxo como uma tabela que cresce, o que reaproveita o SQL e o modelo da etapa anterior — ótimo quando latência de segundos basta. Flink é nativamente por evento e lida melhor com estado grande e latência baixa.\n\nSeja qual for, estude o checkpoint antes de ir a produção: ele é o que define o que acontece quando o processo cai, e cair é certo."}, {"id": "de-str-07", "titulo": "Arquitetura de fluxo e batch", "prioridade": "opcional", "desc": "lambda, kappa, reprocessar do log, duplicação de lógica", "detalhe": "A arquitetura lambda mantém um caminho rápido e um caminho em lote, e paga por isso mantendo a mesma regra escrita duas vezes — que divergem, porque tudo que é escrito duas vezes diverge. A kappa propõe um caminho só, reprocessando do log quando precisa corrigir.\n\nSaiba os nomes para reconhecer qual delas sua empresa tem por acidente."}]}]}, {"id": "producao", "numero": 5, "titulo": "Confiabilidade, custo e governança", "objetivo": "Operar o que você construiu: provar que o dado está certo, saber quanto ele custa e controlar quem o vê.", "descricao": "Pipeline de dados falha de um jeito próprio: ele continua rodando verde e entregando números errados. Software quebrado dá erro; dado quebrado dá resposta. É por isso que esta etapa existe como etapa, e não como apêndice.\n\nAqui entram as três coisas que transformam um projeto em um sistema de que alguém pode depender: teste que roda contra o dado, orçamento que não surpreende, e permissão que não dá acesso a tudo para todos.", "preRequisitos": "Etapa 3 — pode caminhar junto com a 4", "duracao": "4–6 semanas", "grupos": [{"id": "g-de-qualidade", "titulo": "Qualidade e observabilidade", "topicos": [{"id": "de-qa-01", "titulo": "Expectativas sobre o dado", "prioridade": "fundamental", "desc": "unicidade, nulo, faixa de valores, cardinalidade, Great Expectations", "detalhe": "Escreva a expectativa como asserção executável, não como combinado verbal: a chave é única, o valor é positivo, o estado está na lista de estados. Rodando a cada carga, elas pegam a mudança de origem no dia em que ela acontece.\n\nUma expectativa falhando toda semana não é alarme falso: ou ela está errada e precisa ser corrigida, ou o dado está errado e alguém o está usando assim mesmo. As duas conclusões importam."}, {"id": "de-qa-02", "titulo": "Monitorar frescor e volume", "prioridade": "fundamental", "desc": "freshness, contagem de linhas por carga, variação contra a média, detecção de anomalia", "detalhe": "As duas métricas que pegam mais defeito são as mais bobas: quando a tabela foi atualizada pela última vez e quantas linhas entraram. Tabela parada há três dias e carga com um décimo do volume habitual cobrem a maioria dos incidentes reais.\n\nPipeline que termina com sucesso e grava zero linha é o caso que nenhum alerta de falha cobre — e é justamente o que esse monitoramento pega."}, {"id": "de-qa-03", "titulo": "Contrato de dados", "prioridade": "importante", "desc": "esquema acordado, dono da origem, aviso de mudança, versão", "detalhe": "A causa raiz da maioria dos incidentes é alguém da origem mudando algo sem saber que havia consumidor. Contrato é tornar a dependência explícita: estes campos, estes tipos, esta frequência, e aviso antes de mudar.\n\nO contrato vale pelo acordo organizacional, não pelo arquivo. Sem alguém do lado da origem que se reconheça como dono, ele é documentação."}, {"id": "de-qa-04", "titulo": "Reconciliação", "prioridade": "importante", "desc": "conferir total contra a origem, dado faltante, auditoria por lote", "detalhe": "A prova final de que a carga está certa não é o pipeline ter terminado: é o total bater com o sistema de origem. Reconciliação periódica — soma, contagem, por dia — é o que descobre a lacuna de três dias que ninguém notou.\n\nGuarde a métrica por lote. Quando a diferença aparecer, você vai querer saber quando ela começou, e sem histórico isso é arqueologia."}, {"id": "de-qa-05", "titulo": "Incidente de dado", "prioridade": "importante", "desc": "runbook, comunicar o consumidor, correção e reprocessamento, post-mortem", "detalhe": "Avise quem usa antes que a pessoa descubra sozinha — confiança em dado se perde de uma vez e volta devagar. Um painel com aviso de que o número de ontem está sob revisão vale mais do que um painel silenciosamente errado.\n\nDepois do conserto, o post-mortem pergunta por que nenhum teste pegou. A saída de um incidente bem conduzido é sempre uma expectativa nova — é assim que o conjunto de testes cresce com sentido."}]}, {"id": "g-de-infra", "titulo": "Infraestrutura e custo", "topicos": [{"id": "de-inf-01", "titulo": "A nuvem por baixo do dado", "prioridade": "fundamental", "desc": "armazenamento de objetos, computação efêmera, armazém gerenciado, classe de armazenamento", "detalhe": "Armazenamento de objetos — S3 e equivalentes — não é sistema de arquivos: não há renomeação barata nem diretório de verdade, e \"mover pasta\" copia tudo. Vários comportamentos estranhos de pipeline em lake vêm daí.\n\nComputação separada do armazenamento é a mudança que organiza a arquitetura moderna: você desliga o cluster e o dado continua lá, o que também significa que dado parado custa pouco e consulta descuidada custa muito."}, {"id": "de-inf-02", "titulo": "Infraestrutura como código", "prioridade": "importante", "desc": "Terraform, estado, ambiente replicável, mudança revisada", "detalhe": "Recurso criado pelo console não existe para o resto do time e desaparece com quem o criou. Declarado em código, ele é revisável e replicável em outro ambiente — o que é o que torna possível ter homologação de verdade.\n\nO arquivo de estado é o ponto delicado: ele fica remoto, com trava, e não entra no repositório, porque costuma conter valor sensível."}, {"id": "de-inf-03", "titulo": "CI/CD de pipeline", "prioridade": "importante", "desc": "teste na integração, ambiente de homologação, promoção, migração de esquema", "detalhe": "O que roda na integração contínua para um projeto de dados: compilar os modelos, rodar os testes sobre uma amostra e falhar o pull request que quebra a linhagem. É barato e evita a classe inteira de defeito \"a referência aponta para um modelo que não existe mais\".\n\nMigração de esquema precisa ser compatível para trás enquanto o consumidor antigo viver. Em dados, o consumidor antigo é um painel que ninguém lembra que existe."}, {"id": "de-inf-04", "titulo": "Custo", "prioridade": "fundamental", "desc": "cobrança por byte varrido, consulta cara, tabela abandonada, alerta de orçamento", "detalhe": "Em armazém moderno a conta vem de byte lido e de tempo de computação, e o maior ofensor não é o pipeline grande: é o painel que atualiza a cada cinco minutos varrendo a tabela inteira, mais o modelo reconstruído de hora em hora que ninguém consulta há meses.\n\nSaiba achar as consultas mais caras da semana no seu provedor. Essa lista costuma pagar o próprio estudo logo na primeira leitura."}, {"id": "de-inf-05", "titulo": "Desempenho de armazém", "prioridade": "importante", "desc": "clustering, chave de ordenação, poda de partição, tabela agregada", "detalhe": "Armazém colunar não tem índice no sentido do Postgres: o que existe é ordenação física e estatística por bloco, que permitem pular o que não interessa. Ordenar pela coluna que todo mundo filtra é o ajuste que mais rende.\n\nAgregado pré-calculado volta a fazer sentido quando o mesmo painel varre bilhões de linhas por dia. É troca de atualidade por custo — decida conscientemente, porque é um pipeline a mais para manter."}, {"id": "de-inf-06", "titulo": "Monitoramento operacional", "prioridade": "opcional", "desc": "métrica, log centralizado, painel do pipeline, rastro de execução", "detalhe": "Além da qualidade do dado, o pipeline tem saúde própria: duração por execução, taxa de falha, fila de espera. Duração crescendo devagar é o aviso de que o volume está alcançando a janela — meses antes de ela estourar.\n\nÉ o único tipo de alerta desta etapa que se parece com monitoramento de software comum."}]}, {"id": "g-de-governanca", "titulo": "Governança", "topicos": [{"id": "de-gov-01", "titulo": "Acesso e permissão", "prioridade": "fundamental", "desc": "papel, menor privilégio, acesso por coluna e por linha, conta de serviço", "detalhe": "Conceda por papel, nunca por pessoa, e com o mínimo necessário. A conta do pipeline não precisa ler todas as tabelas, e a conta do analista não precisa escrever em nenhuma.\n\nA credencial compartilhada em planilha é o padrão que torna impossível responder quem leu o quê — exatamente a pergunta que o primeiro incidente de privacidade faz."}, {"id": "de-gov-02", "titulo": "Dado pessoal e LGPD", "prioridade": "fundamental", "desc": "minimização, finalidade, prazo de retenção, direito de exclusão", "detalhe": "A obrigação prática que mais muda arquitetura é o direito de exclusão: apagar uma pessoa de um lake imutável, particionado e replicado em cinco camadas exige ter pensado nisso antes. Por isso se centraliza o identificador e se evita espalhá-lo.\n\nMinimização é a defesa mais barata: dado que você não coletou não vaza, não precisa ser apagado e não entra no relatório de incidente."}, {"id": "de-gov-03", "titulo": "Mascaramento e anonimização", "prioridade": "importante", "desc": "hash com sal, pseudonimização, agregação mínima, reidentificação", "detalhe": "Hash sem sal de CPF ou e-mail é reversível por força bruta — o espaço de valores é pequeno e conhecido. Com sal guardado à parte, vira pseudonimização, que ainda é dado pessoal, só menos exposto.\n\nAnonimização de verdade é mais difícil do que parece: poucos atributos cruzados reidentificam uma pessoa num conjunto grande. Por isso a regra de tamanho mínimo de grupo em relatório agregado."}, {"id": "de-gov-04", "titulo": "Catálogo e responsabilidade", "prioridade": "importante", "desc": "glossário, dono por domínio, classificação de sensibilidade, descoberta", "detalhe": "Catálogo resolve menos um problema de busca e mais um de confiança: entre três tabelas com nome parecido, qual é a que vale? A resposta é quem é o dono e quando foi atualizada.\n\nClassificar sensibilidade no catálogo é o que torna a regra de acesso automática em vez de caso a caso — e é o que permite responder onde há dado pessoal sem reler o banco inteiro."}, {"id": "de-gov-05", "titulo": "Depreciar tabela", "prioridade": "opcional", "desc": "aviso, período de convivência, medir quem ainda consulta, remoção", "detalhe": "Antes de apagar, meça: quase todo armazém registra quem consultou o quê. Tabela sem leitura há três meses sai sem drama; tabela com um leitor semanal exige conversa.\n\nApagar sem medir é como quebrar uma API pública sem avisar, com o agravante de que aqui o consumidor descobre por um painel vazio na reunião."}]}]}]}, "PROJETOS": {"fundacoes": ["Carregar um conjunto de dados público grande num Postgres local e responder cinco perguntas de negócio só com SQL.", "Escrever uma consulta que deduplica registros repetidos por `row_number` e provar, contando linhas, que nada se perdeu.", "Fazer um script Python que lê um CSV maior que a memória em blocos e grava um resumo agregado.", "Subir Postgres por `docker compose`, carregar dados por script e versionar tudo num repositório com README que funcione em outra máquina."], "modelagem": ["Modelar um esquema estrela a partir de uma base normalizada, escrevendo o grão da fato em uma frase antes de criar a tabela.", "Implementar uma dimensão tipo 2 e provar que uma consulta histórica devolve o atributo vigente na data do fato.", "Converter o mesmo conjunto de dados para CSV e Parquet e comparar tamanho e tempo de consulta de uma coluna só.", "Particionar por data, medir o volume lido com e sem filtro de partição, e documentar a diferença."], "pipelines": ["Montar um pipeline de ponta a ponta: API ou CSV para camada crua, transformação em SQL, tabela final — com orquestrador.", "Provar a idempotência rodando a mesma execução duas vezes e mostrando que a contagem não mudou.", "Reprocessar um mês inteiro por parâmetro de janela, sem tocar no código.", "Acrescentar testes de unicidade e não nulo nos modelos e fazer o pipeline falhar de propósito ao quebrar um deles."], "escala": ["Processar um conjunto de dados de dezenas de gigabytes e comparar o tempo entre um motor local e um cluster Spark.", "Provocar skew de propósito, identificá-lo no Spark UI e corrigi-lo com salting ou broadcast join.", "Subir Kafka localmente, produzir eventos e consumir com um agregado por janela de tempo de evento.", "Derrubar o consumidor no meio e mostrar que, ao voltar, ele não perdeu nem duplicou mensagem."], "producao": ["Instrumentar um pipeline existente com verificação de frescor e de volume, e disparar alerta de verdade.", "Escrever o runbook de um incidente: como detectar, como corrigir, como reprocessar, quem avisar.", "Achar as cinco consultas mais caras do seu ambiente e reduzir o custo de uma delas com particionamento ou ordenação.", "Criar dois papéis com permissões diferentes e provar que o analista não consegue ler a coluna sensível."]}, "RECURSOS": [{"etapa": "fundacoes", "titulo": "Documentação do PostgreSQL", "url": "https://www.postgresql.org/docs/current/", "nota": "A referência de SQL que também ensina"}, {"etapa": "fundacoes", "titulo": "Use The Index, Luke", "url": "https://use-the-index-luke.com/", "nota": "Índice e plano de execução, do jeito prático"}, {"etapa": "fundacoes", "titulo": "Documentação do pandas", "url": "https://pandas.pydata.org/docs/", "nota": "Comece pelo guia de usuário, não pela API"}, {"etapa": "modelagem", "titulo": "Kimball — técnicas de modelagem dimensional", "url": "https://www.kimballgroup.com/data-warehouse-business-intelligence-resources/kimball-techniques/", "nota": "Fato, dimensão e grão na fonte"}, {"etapa": "modelagem", "titulo": "Documentação do Apache Parquet", "url": "https://parquet.apache.org/docs/", "nota": "Row group, estatística e pushdown"}, {"etapa": "modelagem", "titulo": "Apache Iceberg", "url": "https://iceberg.apache.org/docs/latest/", "nota": "Formato de tabela, snapshot e time travel"}, {"etapa": "pipelines", "titulo": "Documentação do dbt", "url": "https://docs.getdbt.com/", "nota": "ref, materialização e testes"}, {"etapa": "pipelines", "titulo": "Documentação do Apache Airflow", "url": "https://airflow.apache.org/docs/", "nota": "DAG, intervalo de dados e reprocessamento"}, {"etapa": "pipelines", "titulo": "Debezium", "url": "https://debezium.io/documentation/", "nota": "CDC por log de transações"}, {"etapa": "escala", "titulo": "Guia do Apache Spark", "url": "https://spark.apache.org/docs/latest/sql-programming-guide.html", "nota": "DataFrame, plano e ajuste"}, {"etapa": "escala", "titulo": "Documentação do DuckDB", "url": "https://duckdb.org/docs/", "nota": "O motor que evita cluster desnecessário"}, {"etapa": "escala", "titulo": "Documentação do Apache Kafka", "url": "https://kafka.apache.org/documentation/", "nota": "Log particionado, offset e garantias"}, {"etapa": "escala", "titulo": "Apache Flink — conceitos de tempo", "url": "https://nightlies.apache.org/flink/flink-docs-stable/docs/concepts/time/", "nota": "Tempo de evento e marca d'água"}, {"etapa": "producao", "titulo": "Great Expectations", "url": "https://docs.greatexpectations.io/", "nota": "Expectativas executáveis sobre o dado"}, {"etapa": "producao", "titulo": "Documentação do Terraform", "url": "https://developer.hashicorp.com/terraform/docs", "nota": "Infraestrutura declarada e revisável"}, {"etapa": "producao", "titulo": "Lei Geral de Proteção de Dados (Lei 13.709/2018)", "url": "https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm", "nota": "O texto da lei, que é mais curto do que parece"}], "LEGENDA": [{"chave": "fundamental", "rotulo": "Fundamental", "desc": "Ordem estrita. Não pule."}, {"chave": "importante", "rotulo": "Importante", "desc": "Recomendado, mas a ordem é flexível."}, {"chave": "opcional", "rotulo": "Opcional", "desc": "Pule sem culpa e volte depois."}], "ESTADOS": [{"chave": "pendente", "rotulo": "Pendente"}, {"chave": "estudando", "rotulo": "Estudando"}, {"chave": "feito", "rotulo": "Feito"}, {"chave": "pulado", "rotulo": "Pulado"}], "CRITERIOS": ["Se este pipeline rodar duas vezes, o resultado muda?", "Como eu provo que o número está certo, sem pedir para alguém conferir no olho?", "Quando isto falhar às três da manhã, o que o alerta vai dizer e o que eu vou fazer?", "Quanto custa rodar isto, e o que acontece com o custo se o volume dobrar?", "Se a origem mudar uma coluna amanhã, eu descubro pela carga ou pelo painel errado?", "Dá para reprocessar o mês passado sem editar código?"]}$json$::jsonb);
